Idea: treat each city as a node, union every connected pair, and the answer is the number of remaining roots. Path compression plus union by size keeps each find nearly constant, so the matrix scan dominates at O(n²).
```java
class Solution {
    private int[] p, sz;
    private int find(int x) { return p[x] == x ? x : (p[x] = find(p[x])); }
    public int findCircleNum(int[][] isConnected) {
        int n = isConnected.length, cnt = n;
        p = new int[n]; sz = new int[n];
        for (int i = 0; i < n; i++) { p[i] = i; sz[i] = 1; }
        for (int i = 0; i < n; i++)
            for (int j = i + 1; j < n; j++)
                if (isConnected[i][j] == 1) {
                    int a = find(i), b = find(j);
                    if (a == b) continue;
                    if (sz[a] < sz[b]) { int t = a; a = b; b = t; }
                    p[b] = a; sz[a] += sz[b]; cnt--;
                }
        return cnt;
    }
}
